import styles from './pricing.module.css';
import content from '../../data/content.json';

const PricingPage = () => {
    return (
        <div className={styles.container}>
            <section className={styles.intro}>
                <h1 className="section-title">{content.pricing.introTitle}</h1>
                <p className={styles.introText}>
                    {content.pricing.introText}
                </p>
            </section>

            <section className={styles.tariffsSection}>
                <div className={styles.tariffsGrid}>
                    {content.pricing.tariffs.map((tariff: any) => (
                        <div key={tariff.name} className={`${styles.tariffCard} glass-card`}>
                            <h2 className={styles.tariffName}>{tariff.name}</h2>
                            <div className={styles.tariffPrice}>{tariff.price}</div>

                            <div className={styles.tariffDetails}>
                                <div className={styles.detailItem}>
                                    <span className={styles.detailLabel}>Материалы:</span>
                                    <span className={styles.detailValue}>{tariff.materials}</span>
                                </div>
                                <div className={styles.detailItem}>
                                    <span className={styles.detailLabel}>Оборудование:</span>
                                    <span className={styles.detailValue}>{tariff.equipment}</span>
                                </div>
                                <div className={styles.detailItem}>
                                    <span className={styles.detailLabel}>Применение:</span>
                                    <span className={styles.detailValue}>{tariff.usage}</span>
                                </div>
                            </div>

                            <button className="primary-button primary-button--filled" style={{ marginTop: 'auto', width: '100%' }}>
                                Выбрать тариф
                            </button>
                        </div>
                    ))}
                </div>

                <div className={styles.extraInfo}>
                    <div className={styles.extraItem}>
                        <span className={styles.extraLabel}>Минимальный заказ</span>
                        <span className={styles.extraValue}>350 руб.</span>
                    </div>
                    <div className={styles.extraItem}>
                        <span className={styles.extraLabel}>Запуск печати</span>
                        <span className={styles.extraValue}>200 руб.</span>
                    </div>
                    <div className={styles.extraItem}>
                        <span className={styles.extraLabel}>3D Моделирование</span>
                        <span className={styles.extraValue}>от 1000 руб.</span>
                    </div>
                </div>
            </section>

            <section className={styles.faq}>
                <h2 className="section-title" style={{ marginBottom: '60px' }}>FAQ / <span className="accent-text">Вопросы</span></h2>
                <div className={styles.faqList}>
                    <div className={styles.faqItem}>
                        <h3>Как узнать точную цену?</h3>
                        <p>Пришлите нам 3D модель (STL/STEP). Мы загрузим её в слайсер и скажем точное время печати и стоимость.</p>
                    </div>
                    <div className={styles.faqItem}>
                        <h3>Как быстро сделаете?</h3>
                        <p>Благодаря парку из 10 машин, небольшие заказы отдаем в день обращения. Партии — от 2 дней.</p>
                    </div>
                </div>
            </section>
        </div>
    );
};

export default PricingPage;
